ValidationRule.errorConditionFormula:
OR(
    AND(
        ISPICKVAL(Relacionado_a_entrega__c, "Suporte"),
            OR(
                AND(
                    ISBLANK(Numero_do_Contrato__c),
                    NOT(ISBLANK(Relacionado_ao_Projeto__c))
                ),
                AND(
                    NOT(ISBLANK(Numero_do_Contrato__c)),
                    NOT(ISBLANK(Relacionado_ao_Projeto__c))
                )
            )
    ),
    AND(
        ISPICKVAL(Relacionado_a_entrega__c, "Suporte"),
        ISBLANK(Numero_do_Contrato__c)
    )
)
